(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-634":{scenario:{company:"Thiên Trường Structural Engineering",supervisor:{name:"Lương Thế Hiển",role:{vi:"Chủ trì thiết kế kết cấu",en:"Lead Structural Engineer"}},ref_code:"STR-1207",title:{vi:"Đúng công năng. Đúng tải trọng. Đúng an toàn.",en:"Right use. Right load. Right safety margin."},brief:{vi:"Bạn kiểm tra lại thuyết minh STR-1207 cho dầm B3-12 tầng 3 (dầm đơn giản, nhịp 7,2 m, bề rộng chịu tải 2,4 m). Kiến trúc vừa phát hành REV C đổi phòng 3.12 từ văn phòng sang kho lưu trữ hồ sơ. Tĩnh tải tiêu chuẩn trên dầm g = 18 kN/m; hoạt tải tiêu chuẩn mô phỏng: văn phòng 2,0 kPa, kho lưu trữ 5,0 kPa. Hãy sửa loại hoạt tải và mô men uốn tính toán lớn nhất, rồi lập báo cáo có căn cứ.",en:"You are re-checking calculation report STR-1207 for beam B3-12 on level 3 (simply supported, span 7.2 m, tributary width 2.4 m). Architecture has just issued REV C changing room 3.12 from office to archive storage. The characteristic dead load on the beam is g = 18 kN/m; simulated characteristic live loads are 2.0 kPa for offices and 5.0 kPa for archive storage. Correct the live load class and the maximum design bending moment, then write an evidence-based report."},reference_title:{vi:"Bản vẽ kiến trúc REV C & bảng tải trọng đã duyệt",en:"Architecture REV C & approved load schedule"},fields:[{id:"LL_CLASS",label:{vi:"Loại hoạt tải áp cho phòng 3.12",en:"Live load class for room 3.12"},initial:"LL-OFFICE",expected:"LL-STORAGE",choices:["LL-OFFICE","LL-STORAGE","LL-CORRIDOR"],reference:"Bản vẽ kiến trúc REV C",ref_value:{vi:"REV C: phòng 3.12 đổi công năng từ văn phòng sang kho lưu trữ hồ sơ",en:"REV C: room 3.12 changed from office to archive storage"},hint:{vi:"Tải trọng phải theo công năng mới nhất của phòng, không theo bản vẽ phát hành trước.",en:"Loads must follow the room's latest use, not the earlier drawing issue."}},{id:"M_ULS",label:{vi:"Mô men uốn tính toán lớn nhất (kNm)",en:"Maximum design bending moment (kNm)"},initial:"165.6",expected:"221.6",reference:"Bảng tổ hợp tải trọng dầm B3-12",ref_value:{vi:"g = 18 kN/m; hoạt tải theo công năng x bề rộng 2,4 m; nhịp 7,2 m",en:"g = 18 kN/m; live load by use x 2.4 m width; span 7.2 m"},hint:{vi:"Bản nháp vẫn dùng hoạt tải văn phòng; đổi tải theo m2 sang tải theo m dài trước khi tổ hợp.",en:"The draft still uses the office live load; convert the area load to a line load before combining."}}],sop32:{vi:"p = hoạt tải tiêu chuẩn (kPa) x bề rộng chịu tải; q = 1,1 x g + 1,2 x p (hệ số độ tin cậy mô phỏng); dầm đơn giản: M = q x L^2 / 8; ghi M đến 0,1 kNm.",en:"p = characteristic live load (kPa) x tributary width; q = 1.1 x g + 1.2 x p (simulated load factors); simply supported beam: M = q x L^2 / 8; state M to 0.1 kNm."},context:{label:"FEM / STR-1207",metrics:[{label:{vi:"Nhịp dầm",en:"Beam span"},value:"7.2 m"},{label:{vi:"Bề rộng chịu tải",en:"Tributary width"},value:"2.4 m"},{label:{vi:"Tĩnh tải tiêu chuẩn g",en:"Characteristic dead load g"},value:"18 kN/m"}]},terminal:{system:"struct-solver",settable:["LL_CLASS","M_ULS"],commands:[{cmd:"status",out:{vi:"Mô hình STR-1207 đồng bộ kiến trúc REV B; dầm B3-12: hoạt tải LL-OFFICE, M = 165,6 kNm, tỷ số sử dụng 0,78",en:"Model STR-1207 synced to architecture REV B; beam B3-12: live load LL-OFFICE, M = 165.6 kNm, utilization 0.78"}},{cmd:"cat arch-rev.txt",out:{vi:"REV C (phát hành hôm nay): phòng 3.12 đổi từ văn phòng sang kho lưu trữ hồ sơ, giá kệ cao 2,4 m",en:"REV C (issued today): room 3.12 changed from office to archive storage with 2.4 m high shelving"}},{cmd:"cat loads.txt",out:{vi:"Hoạt tải tiêu chuẩn (mô phỏng): văn phòng 2,0 kPa; hành lang 3,0 kPa; kho lưu trữ 5,0 kPa",en:"Characteristic live loads (simulated): office 2.0 kPa; corridor 3.0 kPa; archive storage 5.0 kPa"}},{cmd:"beam info b3-12",out:{vi:"Dầm đơn giản, nhịp 7,2 m, bề rộng chịu tải 2,4 m, tĩnh tải tiêu chuẩn g = 18 kN/m, tiết diện 300 x 600 mm",en:"Simply supported, span 7.2 m, tributary width 2.4 m, characteristic dead load g = 18 kN/m, section 300 x 600 mm"}},{cmd:"run check b3-12",out:{vi:"Cảnh báo: dữ liệu công năng chưa cập nhật REV C; kết quả kiểm tra hiện tại không còn hiệu lực",en:"Warning: occupancy data not updated to REV C; the current check results are no longer valid"}}]},crisis:{vi:"Chủ nhiệm đồ án nhắn: “Sáng mai phải nộp hồ sơ thẩm định. Cứ giữ tải văn phòng, đóng dấu phát hành đi, kho lưu trữ thì sau này chủ đầu tư tự hạn chế xếp hàng.”",en:"The design manager texts: “The submission for appraisal is due tomorrow morning. Keep the office load and stamp it for issue; the owner can just limit storage later.”"},options:{safe:{vi:"Không phát hành bản tính sai tải; cập nhật hoạt tải theo REV C, kiểm tra lại tiết diện, cốt thép và báo chủ trì kết cấu; đề nghị lùi hạn nộp hoặc nộp kèm danh mục hạng mục đang hiệu chỉnh.",en:"Do not issue a calculation with the wrong load; update the live load to REV C, recheck section and reinforcement and inform the lead engineer; request an extension or submit with a list of items under revision."},shortcut:{vi:"Giữ tải văn phòng và đóng dấu phát hành cho kịp hạn, ghi chú hạn chế tải sau.",en:"Keep the office load and stamp the issue to meet the deadline, adding a load restriction note later."},wait:{vi:"Không phát hành nhưng cũng không báo ai, chờ chủ nhiệm đồ án tự phát hiện.",en:"Do not issue but tell no one, waiting for the design manager to notice."}},questions:{vi:["Trình bày cách bạn tính lại q và M sau khi đổi công năng, và hệ quả đối với tỷ số sử dụng của dầm B3-12.","Nếu hồ sơ sai tải đã được phát hành, bạn xử lý thế nào để thu hồi, cập nhật và kiểm soát rủi ro an toàn?"],en:["Explain how you recalculated q and M after the change of use, and the effect on the utilization of beam B3-12.","If the drawings with the wrong load were already issued, how would you withdraw, update and control the safety risk?"]},hints:{vi:["Mở bản vẽ kiến trúc mới nhất và kiểm tra công năng phòng 3.12 trước khi xem kết quả tính.","Theo SOP mục 3.2, đổi hoạt tải từ kPa sang kN/m, nhân hệ số rồi mới tính mô men giữa nhịp.","SOP mục 4.2: không đóng dấu hồ sơ khi dữ liệu đầu vào đã thay đổi; áp lực tiến độ phải báo chủ trì kết cấu."],en:["Open the latest architectural drawing and check the use of room 3.12 before reading the results.","Under SOP 3.2, convert the live load from kPa to kN/m and apply the factors before computing the midspan moment.","SOP 4.2: never stamp drawings when the input data has changed; escalate schedule pressure to the lead engineer."]}},learning:{summary:{vi:"Kỹ sư thiết kế kết cấu xác định tải trọng, lập mô hình phân tích, tính toán và thể hiện bản vẽ cho móng, cột, dầm, sàn, vách của công trình, bảo đảm khả năng chịu lực, độ cứng, ổn định và độ bền lâu dài. Họ phối hợp với kiến trúc, cơ điện và nhà thầu để giải pháp kết cấu vừa an toàn vừa kinh tế. Nghề đòi hỏi nền tảng cơ học vững, hiểu tiêu chuẩn thiết kế và tinh thần trách nhiệm với an toàn cộng đồng.",en:"A structural design engineer defines loads, builds analysis models, designs and details foundations, columns, beams, slabs and walls, ensuring strength, stiffness, stability and durability. They coordinate with architecture, MEP and contractors so the structural solution is both safe and economical. The role requires strong mechanics, command of the design codes and a deep sense of responsibility for public safety."},responsibilities:{vi:["Xác định tải trọng và tác động: tĩnh tải, hoạt tải, gió, động đất theo công năng và vị trí công trình.","Lập mô hình phân tích, tổ hợp tải trọng và kiểm tra các trạng thái giới hạn.","Thiết kế tiết diện, bố trí cốt thép, liên kết và lập bản vẽ kết cấu thi công.","Phối hợp với kiến trúc, cơ điện về lỗ mở, cao độ, thay đổi công năng và trả lời câu hỏi kỹ thuật.","Soát xét chéo bản tính, quản lý phiên bản hồ sơ và giám sát tác giả tại công trường."],en:["Define loads and actions: dead, live, wind and seismic according to use and site.","Build analysis models, combine loads and check the limit states.","Design sections, reinforcement and connections and prepare structural construction drawings.","Coordinate openings, levels and changes of use with architecture and MEP and answer technical queries.","Peer-review calculations, control document revisions and provide designer supervision on site."]},competencies:[{name:{vi:"Cơ học kết cấu",en:"Structural mechanics"},desc:{vi:"Hiểu sự làm việc của hệ chịu lực, nội lực, biến dạng và đường truyền tải.",en:"Understand how structural systems carry load, internal forces, deformation and load paths."}},{name:{vi:"Tiêu chuẩn thiết kế",en:"Design codes"},desc:{vi:"Áp dụng đúng tiêu chuẩn bê tông cốt thép, thép, tải trọng và động đất hiện hành.",en:"Apply current concrete, steel, loading and seismic standards correctly."}},{name:{vi:"Mô hình hóa & phần mềm",en:"Modelling & software"},desc:{vi:"Lập mô hình phần tử hữu hạn đúng điều kiện biên và kiểm tra tính hợp lý của kết quả.",en:"Build finite element models with correct boundary conditions and sanity-check results."}},{name:{vi:"Quản lý thay đổi",en:"Change management"},desc:{vi:"Cập nhật kịp thời khi kiến trúc, công năng hay tải thiết bị thay đổi.",en:"Update promptly when architecture, use or equipment loads change."}},{name:{vi:"Trách nhiệm an toàn",en:"Safety accountability"},desc:{vi:"Không phát hành hồ sơ khi chưa kiểm tra đủ; báo cáo trung thực khi phát hiện sai sót.",en:"Never issue unchecked documents; report honestly when errors are found."}}],knowledge:{vi:["TCVN 2737:2023 - Tải trọng và tác động: tiêu chuẩn thiết kế.","TCVN 5574:2018 - Thiết kế kết cấu bê tông và bê tông cốt thép.","TCVN 5575:2012 - Thiết kế kết cấu thép.","TCVN 9386:2012 - Thiết kế công trình chịu động đất.","Nghị định 06/2021/NĐ-CP về quản lý chất lượng, thi công xây dựng và bảo trì công trình.","Nguyên lý trạng thái giới hạn, tổ hợp tải trọng và hệ số độ tin cậy."],en:["TCVN 2737:2023 - Loads and actions: design standard.","TCVN 5574:2018 - Design of concrete and reinforced concrete structures.","TCVN 5575:2012 - Design of steel structures.","TCVN 9386:2012 - Design of structures for earthquake resistance.","Decree 06/2021/ND-CP on quality management, construction and maintenance of works.","Limit state principles, load combinations and partial load factors."]},tools:["Phần mềm phân tích phần tử hữu hạn nhà cao tầng","Phần mềm thiết kế móng và sàn","Phần mềm mô hình BIM kết cấu","Bảng tính kiểm tra tiết diện","Phần mềm thể hiện bản vẽ CAD"],kpis:{vi:["Số lỗi kết cấu phát hiện sau phát hành (mục tiêu bằng 0).","Tỷ lệ hồ sơ qua thẩm tra không phải chỉnh sửa lớn.","Chỉ tiêu vật liệu (kg thép/m2 sàn) so với mục tiêu dự án.","Thời gian trả lời yêu cầu làm rõ kỹ thuật (RFI)."],en:["Structural errors found after issue (target zero).","Share of designs passing review without major changes.","Material index (kg of rebar per m2 of floor) against the project target.","Response time to requests for information (RFI)."]},day:[{time:"08:00",vi:"Đọc thông báo thay đổi kiến trúc, cơ điện và cập nhật danh sách việc.",en:"Read architectural and MEP change notices and update the task list."},{time:"09:00",vi:"Cập nhật tải trọng, chạy lại mô hình phân tích và kiểm tra chuyển vị, dao động.",en:"Update loads, rerun the analysis model and check drift and vibration."},{time:"13:30",vi:"Thiết kế cốt thép dầm, sàn, kiểm tra cấu tạo và lỗ mở kỹ thuật.",en:"Design beam and slab reinforcement and check detailing and service openings."},{time:"15:30",vi:"Soát xét chéo bản tính của đồng nghiệp, ghi nhận lỗi và đề xuất sửa.",en:"Peer-review a colleague's calculations, log findings and propose fixes."},{time:"17:00",vi:"Trả lời RFI từ công trường và lưu phiên bản hồ sơ.",en:"Answer site RFIs and file the document revision."}],mistakes:{vi:["Không cập nhật tải trọng khi kiến trúc đổi công năng phòng.","Quên đổi tải phân bố trên diện tích sang tải trên chiều dài theo bề rộng chịu tải.","Tin tuyệt đối kết quả phần mềm mà không kiểm tra bằng tính tay đơn giản."],en:["Not updating loads when architecture changes a room's use.","Forgetting to convert area loads to line loads using the tributary width.","Trusting software output blindly without a simple hand check."]},career:[{vi:"Kỹ sư kết cấu tập sự",en:"Graduate structural engineer"},{vi:"Kỹ sư thiết kế kết cấu",en:"Structural design engineer"},{vi:"Chủ trì thiết kế kết cấu",en:"Lead structural engineer"},{vi:"Giám đốc kỹ thuật kết cấu",en:"Structural engineering director"}],glossary:[{term:"ULS",vi:"Trạng thái giới hạn thứ nhất: kết cấu phải đủ khả năng chịu lực, không phá hoại, không mất ổn định.",en:"Ultimate limit state: the structure must resist loads without failure or loss of stability."},{term:"SLS",vi:"Trạng thái giới hạn thứ hai: kiểm soát độ võng, nứt, dao động trong sử dụng bình thường.",en:"Serviceability limit state: controls deflection, cracking and vibration in normal use."},{term:"Tributary width",vi:"Bề rộng diện truyền tải lên cấu kiện, dùng để đổi tải trên m2 thành tải trên m dài.",en:"Width of floor area loading a member, used to convert area loads into line loads."},{term:"Hệ số độ tin cậy",vi:"Hệ số nhân với tải tiêu chuẩn để ra tải tính toán, kể đến sai lệch bất lợi của tải trọng.",en:"Factor applied to characteristic loads to obtain design loads, covering unfavourable deviations."},{term:"Utilization ratio",vi:"Tỷ số giữa nội lực tính toán và khả năng chịu lực; lớn hơn 1 nghĩa là cấu kiện không đạt.",en:"Ratio of design action effect to resistance; above 1 means the member fails the check."}],quiz:[{q:{vi:"Dầm đơn giản nhịp 6 m chịu tải tính toán phân bố đều q = 20 kN/m. Mô men uốn lớn nhất là bao nhiêu?",en:"A simply supported 6 m beam carries a uniform design load q = 20 kN/m. What is the maximum bending moment?"},options:{vi:["60 kNm","120 kNm","90 kNm","180 kNm"],en:["60 kNm","120 kNm","90 kNm","180 kNm"]},answer:2,explain:{vi:"Với dầm đơn giản chịu tải phân bố đều: M = q x L^2 / 8 = 20 x 36 / 8 = 90 kNm.",en:"M = q x L^2 / 8 = 20 x 36 / 8 = 90 kNm."}},{q:{vi:"Hoạt tải sàn 4,0 kPa, bề rộng chịu tải của dầm 3 m. Tải phân bố trên dầm là bao nhiêu?",en:"The floor live load is 4.0 kPa and the beam tributary width is 3 m. What is the line load on the beam?"},options:{vi:["12 kN/m","4 kN/m","1,33 kN/m","7 kN/m"],en:["12 kN/m","4 kN/m","1.33 kN/m","7 kN/m"]},answer:0,explain:{vi:"Tải trên m dài = 4,0 kPa x 3 m = 12 kN/m.",en:"Line load = 4.0 kPa x 3 m = 12 kN/m."}},{q:{vi:"Hồ sơ phải nộp sáng mai nhưng bạn phát hiện tải trọng chưa cập nhật theo công năng mới. Bạn làm gì?",en:"The submission is due tomorrow but you find loads not updated for the new use. What do you do?"},options:{vi:["Đóng dấu phát hành rồi sửa sau","Tự giảm hệ số an toàn cho đủ","Nộp mà không báo ai","Không phát hành bản sai, cập nhật tính toán, báo chủ trì và đề nghị lùi hạn"],en:["Stamp and issue, then fix later","Lower the safety factors until it passes","Submit without telling anyone","Do not issue the wrong version, update it, inform the lead and request an extension"]},answer:3,explain:{vi:"Phát hành bản tính sai tải đe dọa an toàn công trình; phải cập nhật, báo cáo và điều chỉnh tiến độ minh bạch.",en:"Issuing a calculation with wrong loads endangers the building; update, report and adjust the schedule transparently."}},{q:{vi:"Trạng thái giới hạn thứ hai (SLS) kiểm tra nội dung nào?",en:"What does the serviceability limit state (SLS) check?"},options:{vi:["Khả năng chịu lực phá hoại","Độ võng, bề rộng vết nứt và dao động","Ổn định chống lật tổng thể","Cường độ vật liệu ở tuổi 28 ngày"],en:["Failure resistance","Deflection, crack width and vibration","Overall overturning stability","Material strength at 28 days"]},answer:1,explain:{vi:"SLS bảo đảm công trình sử dụng bình thường: võng, nứt, dao động trong giới hạn cho phép.",en:"SLS ensures normal use: deflection, cracking and vibration stay within limits."}}],tools_en:["High-rise finite element analysis software","Foundation and slab design software","Structural BIM modeling software","Section capacity check spreadsheet","CAD drafting software"]}}})})(window.KKR);
